\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT

\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	%axis equal,
	%grid = both,
	xmin = -0.5,
	xmax = 2.0,
	ymin = -0.5,
	ymax = 1.5,
	xtick = {-1.57,1.57},
 	xticklabels = {$0$,$\pi/2$},
  x tick label style={xshift={(\tick<           0)*5pt}},
    x tick label style={xshift={(\tick>0)*-5pt}},
	ytick = {0},
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	% Upper
	\plot[domain=-2+pi/2:2, red, thin, smooth, dashed, variable=\x, samples=200] ({\x},{sin(deg(2*\x))}); 
	\node[red] at (axis cs:1,1.15) {$y=\sin{2x}$};
	\plot[name path=f, domain=0:pi/2, red, very thick, smooth, variable=\x, samples=200] ({\x},{sin(deg(2*\x))});

	% Lower
	\plot[domain=-2+pi/2:2, blue, thin, smooth, dashed, variable=\x, samples=200] ({\x},{0}); 
	\node[blue] at (axis cs:0.5,-0.15) {$y=0$};	
	\plot[name path=g, domain=0:pi/2, blue, very thick, smooth, variable=\x, samples=200] ({\x},{0});

	% Fill
	\plot[deepskyblue!30, fill opacity=0.5] fill between [of=f and g];

	\draw[thick, deepskyblue] (axis cs:4,0) -- (axis cs:4,2);


	\node[black] at (axis cs:0.8,0.35) {$D$};

	\end{axis}
\end{tikzpicture}
\end{document}

